import unittest,subprocess,sys,json
class Tests(unittest.TestCase):
 def test_default_cli(self):
  r=subprocess.run([sys.executable,'cli.py'],text=True,capture_output=True,check=True)
  self.assertEqual(json.loads(r.stdout),{'host':'localhost','port':8080})
 def test_explicit_path(self):
  r=subprocess.run([sys.executable,'cli.py','--config','settings.conf'],text=True,capture_output=True,check=True)
  self.assertEqual(json.loads(r.stdout),{'host':'localhost','port':8080})

